/** 骑行页底部“前方海拔剖面”条：顶基线 + 右侧距离 + 2 px 当前位置。
 *  WP-HELM6：整条 274..315（42 px；WP-HELM5 是 276..315 = 40 px）。
 *  心率带收 2 px、四格上移 3 px 之后把空间还给剖面，画布高 26→28 px。 */
static void ride_elev_strip(void)
{
    lv_obj_t *cv;

    elev_profile_gen();
    (void)B(s_scr, 24, 274, 192, 1, P_HAIR, LV_OPA_COVER, 0); /* 顶部基线 */
    (void)LW(s_scr, "前方 2 km", PX_MICRO, P_MUTE, 120, 275, 96,
             LV_TEXT_ALIGN_RIGHT);
    /* 当前位置 = 剖面左端：2 px 竖线。 */
    (void)B(s_scr, 24, 288, 2, ELEV_CANVAS_H, P_INK, LV_OPA_COVER, 0);
    cv = lv_canvas_create(s_scr);
    lv_obj_remove_flag(cv, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(cv, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_pos(cv, 26, 288);
    lv_canvas_set_buffer(cv, s_elev_cbuf, ELEV_CANVAS_W, ELEV_CANVAS_H,
                         LV_COLOR_FORMAT_RGB565);
    lv_obj_set_size(cv, ELEV_CANVAS_W, ELEV_CANVAS_H);
    elev_canvas_paint(cv, ELEV_CANVAS_W, ELEV_CANVAS_H, false);
}

/* ── 第 11 屏「海拔」：整页剖面 + 当前坡度 / 累计爬升 / 最高点 ──────
 * 可选屏，`SIM_HELM_SCREEN=elevation` 直达（与 icons / iconopt 同类调试屏，
 * 不进十屏巡页，也不改导航页 KEY1 的既有行为）。 */
#define ELEV_BIG_W 190
#define ELEV_BIG_H 150
static uint8_t s_elev_big_cbuf[ELEV_BIG_W * ELEV_BIG_H * 2]
    __attribute__((aligned(4)));

/** 一列统计：11px 标签 + 22px 数值 + 11px 单位。 */
static void elev_stat(int x, const char *lab, const char *val,
                      const char *unit)
{
    L(s_scr, lab, PX_MICRO, P_MUTE, x, 236);
    (void)L(s_scr, val, PX_VALUE, P_INK, x, 250);
    L(s_scr, unit, PX_MICRO, P_MUTE, x + text_width(val, PX_VALUE) + 3, 261);
}

static void elev_build(void)
{
    lv_obj_t *cv;
    const double step = ELEV_VIEW_M / (double)(ELEV_PROF_N - 1);
    double gain = 0;
    double mn;
    double mx;
    int peak = 0;
    char buf[32];

    d_bg(s_scr, P_PAPER);
    TOP(s_scr, "海拔", "前方 2 km");
    elev_profile_gen();
    mn = s_elev[0];
    mx = s_elev[0];
    for (int i = 0; i + 1 < ELEV_PROF_N; i++) {
        if (s_elev[i + 1] > s_elev[i]) {
            gain += s_elev[i + 1] - s_elev[i];
        }
    }
    for (int i = 1; i < ELEV_PROF_N; i++) {
        if (s_elev[i] < mn) mn = s_elev[i];
        if (s_elev[i] > mx) {
            mx = s_elev[i];
            peak = i;
        }
    }

    L(s_scr, "海拔 m", PX_MICRO, P_MUTE, 24, 40);
    snprintf(buf, sizeof(buf), "%d–%d m", (int)lround(mn), (int)lround(mx));
    LW(s_scr, buf, PX_MICRO, P_MUTE, 120, 40, 96, LV_TEXT_ALIGN_RIGHT);

    /* 当前位置竖线 + 大图（190×150）。 */
    (void)B(s_scr, 24, 56, 2, ELEV_BIG_H, P_INK, LV_OPA_COVER, 0);
    cv = lv_canvas_create(s_scr);
    lv_obj_remove_flag(cv, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(cv, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_pos(cv, 26, 56);
    lv_canvas_set_buffer(cv, s_elev_big_cbuf, ELEV_BIG_W, ELEV_BIG_H,
                         LV_COLOR_FORMAT_RGB565);
    lv_obj_set_size(cv, ELEV_BIG_W, ELEV_BIG_H);
    elev_canvas_paint(cv, ELEV_BIG_W, ELEV_BIG_H, true);

    /* 横轴：0 / 1 km / 2 km。 */
    (void)B(s_scr, 24, 210, 192, 1, P_HAIR, LV_OPA_COVER, 0);
    L(s_scr, "0", PX_MICRO, P_MUTE, 24, 212);
    LW(s_scr, "1 km", PX_MICRO, P_MUTE, 96, 212, 48, LV_TEXT_ALIGN_CENTER);
    LW(s_scr, "2 km", PX_MICRO, P_MUTE, 168, 212, 48, LV_TEXT_ALIGN_RIGHT);

    snprintf(buf, sizeof(buf), "%.1f",
             grade_val((s_elev[1] - s_elev[0]) / step * 100.0));
    elev_stat(24, "当前坡度", buf, grade_unit());
    snprintf(buf, sizeof(buf), "%d", (int)lround(gain));
    elev_stat(96, "累计爬升", buf, "m");
    snprintf(buf, sizeof(buf), "%d", (int)lround(mx));
    elev_stat(168, "最高点", buf, "m");
    snprintf(buf, sizeof(buf), "最高点在前方 %.1f km",
             (double)peak * step / 1000.0);
    LW(s_scr, buf, PX_MICRO, P_MUTE, 24, 286, 192, LV_TEXT_ALIGN_CENTER);
}

static void ride_refresh_dial(void)
{
    char buf[32];

    if (UR.arc == NULL) {
        return;
    }
    lv_arc_set_value(UR.arc, (int)lround(R.speed));
    snprintf(buf, sizeof(buf), "%.1f", conv_speed(R.speed));
    lv_label_set_text(UR.hero, buf);
    lv_obj_set_style_text_color(UR.hero,
                                lv_color_hex(R.paused ? P_TRACK : P_INK), 0);
    if (UR.unit != NULL) {
        lv_label_set_text(UR.unit, unit_speed());
        lv_obj_set_style_text_color(UR.unit,
                                    lv_color_hex(R.paused ? P_TRACK : P_MUTE),
                                    0);
    }
    snprintf(buf, sizeof(buf), "%d", R.hr);
    if (UR.hr_val != NULL) {
        const int z = hr_zone(R.hr);
        const int bx0 = HR_BAR_X0 + (z - 1) * HR_BAR_W / 5;
        const int bx1 = HR_BAR_X0 + z * HR_BAR_W / 5;

        lv_label_set_text(UR.hr_val, buf);
        /* 单位紧跟数值（advance 宽度 + 4 px ≈ 6 px 墨迹间隙），不再右对齐。 */
        lv_obj_set_x(UR.hr_unit, 24 + text_width(buf, PX_VALUE) + 4);
        /* 分区 = 指针位置 + 当前格 1px 描边；格子底色不变。 */
        lv_obj_set_x(UR.hr_ptr, hr_bar_x(R.hr));
        lv_obj_set_pos(UR.hr_sel, bx0, HR_BAR_Y);
        lv_obj_set_size(UR.hr_sel, bx1 - bx0, HR_BAR_H);
        lv_obj_set_style_border_color(UR.hr_sel,
                                      lv_color_hex(HR_ZONE_LINE[z - 1]), 0);
        {
            char b[48];
            int avg;
            int peak;

            hr_hist_stats(&avg, &peak);
            snprintf(b, sizeof(b), "均 %d · 峰 %d", avg, peak);
            lv_label_set_text(UR.hr_stats, b);
        }
    }
    {
        int x = SPD_BAR_X0 + (int)lround((double)SPD_BAR_W * R.speed / 60.0) - 1;

        if (x < SPD_BAR_X0 + 1) x = SPD_BAR_X0 + 1;
        if (x > SPD_BAR_X0 + SPD_BAR_W - 4) x = SPD_BAR_X0 + SPD_BAR_W - 4;
        lv_obj_set_x(UR.cursor, x);
    }
    {
        const char *vals[4];
        char b0[24], b1[24], b2[24], b3[24];

        /* 表盘页固定四格（里程 / 时间 / 踏频 / 海拔）；其它数据在数字页。 */
        snprintf(b0, sizeof(b0), "%.1f", conv_dist(R.dist_km));
        snprintf(b1, sizeof(b1), "%u:%02u",
                 (unsigned)(R.elapsed_s / 60),
                 (unsigned)(R.elapsed_s % 60));
        snprintf(b2, sizeof(b2), "%d", R.cadence);
        snprintf(b3, sizeof(b3), "%d", R.elevation);
        vals[0] = b0; vals[1] = b1; vals[2] = b2; vals[3] = b3;
        for (int i = 0; i < 4; i++) {
            lv_label_set_text(UR.metrics[i], vals[i]);
        }
    }
}

/* 第 2 页（纯数字栅格）：8 格值，等宽右对齐；暂停时数字退灰。 */
static void ride_refresh_grid(void)
{
    char b[8][24];
    const uint32_t ink = R.paused ? P_TRACK : P_INK;

    if (UR.gv[0] == NULL) {
        return;
    }
    snprintf(b[0], sizeof(b[0]), "%.1f", conv_speed(R.speed));
    snprintf(b[1], sizeof(b[1]), "%.1f", conv_speed(R.avg));
    snprintf(b[2], sizeof(b[2]), "%.1f", conv_dist(R.dist_km));
    snprintf(b[3], sizeof(b[3]), "%u:%02u",
             (unsigned)(R.elapsed_s / 60), (unsigned)(R.elapsed_s % 60));
    snprintf(b[4], sizeof(b[4]), "%d", R.hr);
    snprintf(b[5], sizeof(b[5]), "%d", R.cadence);
    snprintf(b[6], sizeof(b[6]), "%d", R.elevation);
    snprintf(b[7], sizeof(b[7]), "%+.1f", grade_val(R.grade));
    for (int i = 0; i < 8; i++) {
        lv_label_set_text(UR.gv[i], b[i]);
        lv_obj_set_style_text_color(UR.gv[i], lv_color_hex(ink), 0);
    }
}

/* 第 3 页（全屏地图）：速度大字 + 右半块（转向 / 本次骑行时长）+ 已骑里程。 */
static void ride_refresh_map(void)
{
    char buf[32];

    if (UR.map_speed == NULL) {
        return;
    }
    snprintf(buf, sizeof(buf), "%.1f", conv_speed(R.speed));
    lv_label_set_text(UR.map_speed, buf);
    lv_obj_set_style_text_color(UR.map_speed,
                                lv_color_hex(R.paused ? P_TRACK : P_INK), 0);
    if (UR.map_unit != NULL) {
        lv_label_set_text(UR.map_unit, unit_speed());
        /* 单位固定在数值下方一行（卡内 14,44），不随位数右移。 */
    }
    if (UR.map_turn != NULL) {
        if (s_nav_active) {
            const int m = 480 - (int)(R.elapsed_s * 10) % 480;

            snprintf(buf, sizeof(buf), "%d m", ((m <= 0 ? 480 : m) / 10) * 10);
            lv_label_set_text(UR.map_turn, buf);
            lv_label_set_text(UR.map_turn_sub, NAV_TURNS[s_nav_turn % 4]);
        } else {
            /* 未导航：右半块显示本次骑行时长（与数字页同一格式）。 */
            snprintf(buf, sizeof(buf), "%u:%02u",
                     (unsigned)(R.elapsed_s / 60),
                     (unsigned)(R.elapsed_s % 60));
            lv_label_set_text(UR.map_turn, buf);
            lv_label_set_text(UR.map_turn_sub, "本次骑行");
        }
    }
    if (UR.map_dist != NULL) {
        snprintf(buf, sizeof(buf), "已骑 %.1f %s", conv_dist(R.dist_km),
                 unit_dist());
        lv_label_set_text(UR.map_dist, buf);
    }
}

static void ride_refresh(void)
{
    if (s_ride_page == 1) {
        ride_refresh_grid();
    } else if (s_ride_page == 2) {
        ride_refresh_map();
    } else {
        ride_refresh_dial();
    }
}

static void ride_page_types(void)
{
    char lab[4][24];

    snprintf(lab[0], sizeof(lab[0]), "里程 %s", unit_dist());
    snprintf(lab[1], sizeof(lab[1]), "时间");
    snprintf(lab[2], sizeof(lab[2]), "踏频 rpm");
    snprintf(lab[3], sizeof(lab[3]), "海拔 m");
    for (int i = 0; i < 4; i++) {
        lv_obj_t *parent = lv_obj_get_parent(UR.metrics[i]);

        lv_label_set_text(lv_obj_get_child(parent, 0), lab[i]);
    }
}

/* ── 共用状态栏（环形页 + 三个骑行页同一套；y=0..24，内容从 y≥24）──
 *
 * 两簇对齐（按**墨迹**而不是对象框）：
 *   左簇：时间 + GPS BLE 心率 功率 踏频，墨迹 x0=12，时间→GPS 8px，图标间 4px；
 *   右簇：REC + NAV + 电量，墨迹 x1=216，REC→NAV 4px，NAV→电量 8px，
 *         电量图标→文字 7px；NAV/REC 隐藏时整簇右移（间隙不变）；
 *   两簇之间弹性空白（space-between）。
 *
 * 图标是**原生 14px** 位图（helm_icons_14.c），不再把 20px 字形用
 * transform_scale 缩放（6× 下会糊成一团）。每个字形的墨迹宽/偏置集中在
 * 下面的 SB_INK[]，数值全部实测——改字形后必须重测：
 * docs/agent/evidence/WP-HELM9/R1/A/statusbar_coords.md（measure.py 生成）。
 */
#define SB_ICON_PX          14
#define SB_INK_GAP_TIME     8
#define SB_INK_GAP_ICON     4
#define SB_INK_GAP_REC_NAV  4
#define SB_INK_GAP_NAV_BAT  8
#define SB_INK_GAP_BAT_TXT  7
#define SB_REC_D            5      /* REC 实心点直径 */
#define SB_TIME_X           12
#define SB_BAT_TXT_X        193
#define SB_BAT_TXT_W        24
#define SB_MIN_BLANK        12

enum { SB_GPS, SB_BLE, SB_HR, SB_PWR, SB_CAD, SB_NAV, SB_BAT, SB_ICON_N };

/* 14px 字形墨迹：ink_w = 墨迹宽（BLE 含 3px 连接点）；
 * cx_off = 对象中心 − 墨迹左沿（补偿 side bearing）；
 * dot_dx = 连接点墨迹左沿 − 字形墨迹左沿（-1 = 不画点）。 */
typedef struct {
    helm_icon_t id;
    int ink_w;
    int cx_off;
    int dot_dx;
} sb_ink_t;

static const sb_ink_t SB_INK[SB_ICON_N] = {
    [SB_GPS] = { HELM_ICON_GPS,     14, 7, 11 },
    [SB_BLE] = { HELM_ICON_BLE,     13, 4, 10 },  /* 7 字形 + 3 + 3 点 */
    [SB_HR]  = { HELM_ICON_HR,      12, 6, -1 },
    [SB_PWR] = { HELM_ICON_POWER,    9, 5, -1 },
    [SB_CAD] = { HELM_ICON_CADENCE, 10, 5, -1 },
    [SB_NAV] = { HELM_ICON_NAV,     10, 5, -1 },
    [SB_BAT] = { HELM_ICON_BATTERY, 12, 6, -1 },
};

typedef struct {
