    int pos[5];
    int rpos[3];
    bool show_ble = true;
    bool cluster_off = !s_sens_on[0] && !s_sens_on[1] && !s_sens_on[2];
    bool show_hr = !cluster_off;
    bool show_pwr = !cluster_off;
    bool show_cad = !cluster_off;
    bool show_nav = s_nav_active;
    bool show_rec = R.active && R.rec;
    int left_end;
    int right_left;
    int txt_x0;
    int x0;

    memset(&SB, 0, sizeof(SB));
    (void)B(s_scr, 0, 0, 240, 24, P_PAPER, LV_OPA_COVER, 0);
    HAIR(s_scr, 0, 23, 240);

    /* ① 时间：墨迹 x0=12（12px，贴左）。 */
    snprintf(tbuf, sizeof(tbuf), "%d:%02d", (s_min / 60) % 24, s_min % 60);
    SB.time_l = LW(s_scr, tbuf, 12, P_INK, SB_TIME_X, 4,
                   text_width(tbuf, 12) + 2, LV_TEXT_ALIGN_LEFT);
    time_end = SB_TIME_X + text_width(tbuf, 12) - 1;

    /* ② 电量文字（右对齐到墨迹 x1=216）先算：右簇从它往左排。 */
    snprintf(tbuf, sizeof(tbuf), "%d%%", s_batt);
    txt_x0 = SB_BAT_TXT_X + SB_BAT_TXT_W - text_width(tbuf, 10);

    /* ③ 左簇墨迹布局 + 碰撞保护（隐藏顺序 踏频→功率→NAV→BLE）。 */
    x0 = time_end + 1 + SB_INK_GAP_TIME;
    for (int guard = 0; guard < 5; guard++) {
        left_end = left_cluster_layout(x0, show_ble, show_hr, show_pwr,
                                       show_cad, pos);
        right_left = right_cluster_layout(show_rec, show_nav, txt_x0, rpos);
        if (right_left - left_end - 1 >= SB_MIN_BLANK) {
            break;
        }
        if (show_cad) {
            show_cad = false;
            printf("helm: statusbar collision -> hide cadence\n");
        } else if (show_pwr) {
            show_pwr = false;
            printf("helm: statusbar collision -> hide power\n");
        } else if (show_nav) {
            show_nav = false;
            printf("helm: statusbar collision -> hide NAV\n");
        } else if (show_ble) {
            show_ble = false;
            printf("helm: statusbar collision -> hide BLE\n");
        } else {
            break;
        }
    }
    left_end = left_cluster_layout(x0, show_ble, show_hr, show_pwr, show_cad,
                                   pos);
    right_left = right_cluster_layout(show_rec, show_nav, txt_x0, rpos);

    if (pos[0] >= 0) {
        icon_at_ink(SB_GPS, pos[0], s_gps > 0);
    }
    if (pos[1] >= 0) {
        icon_at_ink(SB_BLE, pos[1], s_ble_on);
    }
    if (pos[2] >= 0) {
        icon_at_ink(SB_HR, pos[2], s_sens_on[0]);
    }
    if (pos[3] >= 0) {
        icon_at_ink(SB_PWR, pos[3], s_sens_on[2]);
    }
    if (pos[4] >= 0) {
        icon_at_ink(SB_CAD, pos[4], s_sens_on[1]);
    }

    /* ④ 右簇：REC / NAV / 电量从右往左排（墨迹间隙固定，隐藏时自动右移）。 */
    SB.batt_i = sb_icon(s_scr, SB_BAT, rpos[2],
                        s_batt < 20 ? P_RED : P_INK);
    if (rpos[1] >= 0) {
        SB.nav_i = sb_icon(s_scr, SB_NAV, rpos[1], C_DEEP[M_NAV]);
    }
    if (rpos[0] >= 0) {
        SB.rec_dot = B(s_scr, rpos[0], 9, SB_REC_D, SB_REC_D, P_RED,
                       LV_OPA_COVER, 2);
    }
    snprintf(tbuf, sizeof(tbuf), "%d%%", s_batt);
    SB.batt_l = LW(s_scr, tbuf, 10,
                   s_batt < 20 ? P_RED : P_INK, SB_BAT_TXT_X, 6,
                   SB_BAT_TXT_W, LV_TEXT_ALIGN_RIGHT);

    statusbar_refresh();
}

/** 三页指示点：y=26..33，位于状态栏下方的内容区左上角。 */
static void ride_page_dots(void)
{
    for (int i = 0; i < 3; i++) {
        (void)B(s_scr, 12 + i * 10, 26, 7, 7,
                i == s_ride_page ? C_DEEP[M_RIDE] : P_TRACK,
                LV_OPA_COVER, 3);
    }
}

/* 第 1 页：270° 仪表 + 大时速（原骑行页，保留）。 */
static void ride_build_dial(void)
{
    lv_obj_t *arc;
    lv_obj_t *hero_box;

    /* 270° 仪表：中心 (120,106)、d=152、7px（与盘面收缩后的几何对位）。 */
    arc = lv_arc_create(s_scr);
    lv_obj_set_size(arc, 152, 152);
    lv_obj_set_pos(arc, 44, 30);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_all(arc, 0, 0);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(arc, 0, 0);
    lv_obj_set_style_outline_width(arc, 0, 0);
    lv_obj_set_style_shadow_width(arc, 0, 0);
    lv_obj_set_style_arc_width(arc, 7, LV_PART_MAIN);
    lv_obj_set_style_arc_color(arc, lv_color_hex(P_TRACK), LV_PART_MAIN);
    lv_obj_set_style_arc_rounded(arc, true, LV_PART_MAIN);
    lv_obj_set_style_arc_width(arc, 7, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(arc, lv_color_hex(C_DEEP[M_RIDE]),
                               LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(arc, true, LV_PART_INDICATOR);
    lv_obj_set_style_bg_color(arc, lv_color_hex(P_INK), LV_PART_KNOB);
    lv_obj_set_style_bg_opa(arc, LV_OPA_COVER, LV_PART_KNOB);
    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
    lv_obj_set_style_pad_all(arc, 3, LV_PART_KNOB);
    lv_arc_set_bg_angles(arc, 0, 270);
    lv_arc_set_rotation(arc, 135);
    lv_arc_set_range(arc, 0, 60);
    lv_arc_set_value(arc, (int)lround(R.speed));
    UR.arc = arc;

    /* 刻度外径 82：12 点方向墨迹正好落在 y=24（状态栏占 0..23），再加大
     * 就会穿出发丝线；这是几何约束，不是随手取的数。 */
    for (int i = 0; i < 7; i++) {
        lv_point_precise_t pts[2];
        const double a = (double)(225 + i * 45) * DEG2RAD;

        pts[0].x = 120 + (int)lround(sin(a) * 78);
        pts[0].y = 106 - (int)lround(cos(a) * 78);
        pts[1].x = 120 + (int)lround(sin(a) * 82);
        pts[1].y = 106 - (int)lround(cos(a) * 82);
        (void)LINE(s_scr, pts, 2, 1, P_TICK);
    }

    /* hero：容器整体做 0→100% 淡入（ANIMATION #3 的阶段 C）。 */
    hero_box = lv_obj_create(s_scr);
    lv_obj_remove_style_all(hero_box);
    lv_obj_set_pos(hero_box, 40, 64);
    lv_obj_set_size(hero_box, 160, 72);
    lv_obj_remove_flag(hero_box, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(hero_box, LV_OBJ_FLAG_CLICKABLE);
    UR.hero_box = hero_box;
    {
        lv_obj_t *stack = d_stack(hero_box, 0, 0, 160, 56,
                                  LV_FLEX_ALIGN_CENTER, 0);

        UR.hero = lv_label_create(stack);
        lv_obj_set_style_text_font(UR.hero, F(PX_HERO), 0);
        lv_obj_set_style_text_color(UR.hero,
                                    lv_color_hex(R.paused ? P_TRACK : P_INK), 0);
    }
    UR.unit = LW(hero_box, unit_speed(), PX_SMALL, P_MUTE, 0, 56, 160,
                 LV_TEXT_ALIGN_CENTER);

    /* 速度带（WP-HELM6 第二步）：满内容宽 x=24..216（w=192），与四格/剖面同轴。
     * `速度` 文字删掉：上方 hero “22.0 km/h” 已经说明量纲，再写一遍是冗余；
     * 删掉后这一行只剩“带 + 刻度”，两条带结构完全对称（值在上、带在下）。
     * 三段 96/48/48 = 0-30/30-45/45-60；刻度 0/30/60 仍在带内。 */
    {
        const int x0 = SPD_BAR_X0, w = SPD_BAR_W;
        const int w1 = w / 2, w2 = w / 4;

        (void)B(s_scr, x0, SPD_BAR_Y, w1, SPD_BAR_H, C_LIGHT[M_NAV],
                LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1, SPD_BAR_Y, w2, SPD_BAR_H, C_LIGHT[M_RIDE],
                LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1 + w2, SPD_BAR_Y, w2, SPD_BAR_H,
                C_LIGHT[M_RECORD], LV_OPA_COVER, 0);
        (void)B(s_scr, x0, SPD_BAR_Y, w1, 2, C_DEEP[M_NAV], LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1, SPD_BAR_Y, w2, 2, C_DEEP[M_RIDE],
                LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1 + w2, SPD_BAR_Y, w2, 2, C_DEEP[M_RECORD],
                LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1, SPD_BAR_Y, 1, SPD_BAR_H, P_INK, LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1 + w2, SPD_BAR_Y, 1, SPD_BAR_H, P_INK,
                LV_OPA_COVER, 0);
        {
            char b[8];

            L(s_scr, "0", PX_MICRO, P_INK, x0 + 4, SPD_BAR_Y + 2);
            snprintf(b, sizeof(b), "%.0f", conv_speed(30.0));
            L(s_scr, b, PX_MICRO, P_INK, x0 + w1 + 3, SPD_BAR_Y + 2);
            snprintf(b, sizeof(b), "%.0f", conv_speed(60.0));
            L(s_scr, b, PX_MICRO, P_INK, x0 + w - 16, SPD_BAR_Y + 2);
        }
        UR.cursor = B(s_scr, x0 + (int)lround(w * R.speed / 60.0) - 1,
                      SPD_BAR_Y - 1, BAR_PTR_W, BAR_PTR_H, P_INK,
                      LV_OPA_COVER, 1);
    }

    /* 心率行（WP-HELM6 第二步）：「心率 Z4」标签删掉，只留值 + 单位。
     *   第 1 行 “148” 22px，左对齐 x=24；单位 “bpm” 12px 紧跟其后
     *          （x 由 ride_refresh 按 advance 宽度重算，不再右对齐 216）；
     *   第 2 行 5 分区色带 x=24,w=192,y=223,h=18（满内容宽，与四格/剖面同轴）；
     *          当前分区 = 2px 竖线指针（与速度指针同规格）+ 当前格 1px 深色
     *          描边；格子底色只有浅色阶梯，没有整格深色填充。
     * 竖直：速度带 184..201、值墨迹 204..220、色带 223..240；比 WP-HELM5
     *       （色带 224..243、高 20）上移 1 px、矮 2 px，收回的 3 px 给了剖面。 */
    {
        const int x0 = HR_BAR_X0, w = HR_BAR_W;

        UR.hr_val = L(s_scr, "148", PX_VALUE, P_INK, 24, 199);
        UR.hr_unit = L(s_scr, "bpm", PX_SMALL, P_MUTE, 64, 206);
        /* 右侧次级统计「均 133 · 峰 148」：11 px 次要色，盒 120..215
         * 右对齐 216，与 148 同一行；文本由 ride_refresh 现算填入。 */
        UR.hr_stats = LW(s_scr, "", PX_MICRO, P_MUTE, 120, 206, 96,
                         LV_TEXT_ALIGN_RIGHT);
        for (int i = 0; i < 5; i++) {
            const int bx = x0 + i * w / 5;
            const int bw = x0 + (i + 1) * w / 5 - bx;

            UR.hr[i] = B(s_scr, bx, HR_BAR_Y, bw, HR_BAR_H, HR_ZONE_LIGHT[i],
                         LV_OPA_COVER, 0);
        }
        for (int i = 1; i < 5; i++) {
            (void)B(s_scr, x0 + i * w / 5, HR_BAR_Y, 1, HR_BAR_H, P_TICK,
                    LV_OPA_COVER, 0);
        }
        /* 当前格：只有 1px 边、没有底（bg 透明），所以不会变成深色块。 */
        UR.hr_sel = lv_obj_create(s_scr);
        lv_obj_remove_style_all(UR.hr_sel);
        lv_obj_set_pos(UR.hr_sel, x0 + 3 * w / 5, HR_BAR_Y);
        lv_obj_set_size(UR.hr_sel, x0 + 4 * w / 5 - (x0 + 3 * w / 5),
                        HR_BAR_H);
        lv_obj_remove_flag(UR.hr_sel, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_remove_flag(UR.hr_sel, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_set_style_bg_opa(UR.hr_sel, LV_OPA_TRANSP, 0);
        lv_obj_set_style_radius(UR.hr_sel, 0, 0);
        lv_obj_set_style_border_width(UR.hr_sel, 1, 0);
        lv_obj_set_style_border_opa(UR.hr_sel, LV_OPA_COVER, 0);
        lv_obj_set_style_border_color(UR.hr_sel,
                                      lv_color_hex(HR_ZONE_LINE[3]), 0);
        /* 指针最后建、压在最上层：落在格线上也读得清。 */
        UR.hr_ptr = B(s_scr, hr_bar_x(R.hr), BAR_PTR_Y, BAR_PTR_W, BAR_PTR_H,
                      P_INK, LV_OPA_COVER, 1);
    }

    /* 4 个指标（KEY1 短按切页，0ms 硬切）。WP-HELM6：心率带高 20→18，
     * 整行从 y=245 上移到 y=242（盒高 30、盒内间距 12 都不变），
     * 墨迹 244..268；给底部海拔剖面留 274..315（42 px）。字号/文案/列宽不变。 */
    {
        static const int cx[4] = { 48, 96, 144, 192 };

        for (int i = 0; i < 4; i++) {
            lv_obj_t *box = lv_obj_create(s_scr);

            lv_obj_remove_style_all(box);
            lv_obj_set_pos(box, cx[i] - 30, 242);
            lv_obj_set_size(box, 60, 30);
            lv_obj_remove_flag(box, LV_OBJ_FLAG_SCROLLABLE);
            lv_obj_remove_flag(box, LV_OBJ_FLAG_CLICKABLE);
            {
                lv_obj_t *lab = LW(box, "", PX_MICRO, P_MUTE, 0, 0, 60,
                                   LV_TEXT_ALIGN_CENTER);
                lv_obj_t *val = LW(box, "", PX_BODY, P_INK, 0, 12, 60,
                                   LV_TEXT_ALIGN_CENTER);

                (void)lab;
                UR.metrics[i] = val;
            }
        }
    }
    ride_elev_strip();
    ride_page_types();
    ride_refresh();
}

/* ── 第 2 页：专业数字页（无表盘，2 列 × 4 行纯数据栅格）──────────
 * 8 格：时速 / 均速 / 里程 / 时间 / 心率 / 踏频 / 海拔 / 坡度。
 * 每格 = 11px 标签 + 22px（时速 30px）数值 + 11px 单位；数值在固定宽度盒
 * 里右对齐、单位从同一 x 起排，形成两条严格对齐的数字列（MiSans 数字
 * 为等宽字形）。暂停时数字退到 P_TRACK，单位保持 P_MUTE。 */
static void ride_build_grid(void)
{
    static const char *const LAB[8] = {
        "时速", "均速", "里程", "时间",
        "心率", "踏频", "海拔", "坡度",
    };
    const char *unit[8];
    char ub[8][12];
    const int cx[2] = { 12, 124 };
    const int cy[4] = { 40, 108, 176, 244 };
    const int cw = 104;
    const int ch = 64;

    snprintf(ub[0], sizeof(ub[0]), "%s", unit_speed());
    snprintf(ub[1], sizeof(ub[1]), "%s", unit_speed());
    snprintf(ub[2], sizeof(ub[2]), "%s", unit_dist());
    snprintf(ub[3], sizeof(ub[3]), "%s", "");
    snprintf(ub[4], sizeof(ub[4]), "bpm");
    snprintf(ub[5], sizeof(ub[5]), "rpm");
    snprintf(ub[6], sizeof(ub[6]), "m");
    snprintf(ub[7], sizeof(ub[7]), "%s", grade_unit());
    for (int i = 0; i < 8; i++) {
        unit[i] = ub[i];
    }

    for (int i = 0; i < 8; i++) {
        const int col = i % 2;

        const int col = i % 2;
        const int row = i / 2;
        lv_obj_t *card = B(s_scr, cx[col], cy[row], cw, ch, P_CARD,
                           LV_OPA_COVER, 8);
        const int vpx = (i == 0) ? 30 : PX_VALUE;

        lv_obj_set_style_border_width(card, 1, 0);
        lv_obj_set_style_border_color(card, lv_color_hex(P_HAIR), 0);
        lv_obj_set_style_border_opa(card, LV_OPA_COVER, 0);
        /* 小色条：一眼区分两列（左=骑行绿，右=记录橙）。 */
        (void)B(card, 0, 10, 3, 16,
                col == 0 ? C_DEEP[M_RIDE] : C_DEEP[M_RECORD], LV_OPA_COVER,
                1);
        (void)L(card, LAB[i], PX_MICRO, P_MUTE, 10, 5);
        UR.gv[i] = LW(card, "", vpx, P_INK, 4, (i == 0) ? 17 : 24, 62,
                      LV_TEXT_ALIGN_RIGHT);
        (void)L(card, unit[i], PX_MICRO, P_MUTE, 68,
                (i == 0) ? 42 : 44);
    }
    ride_refresh();
}

/* ── 第 3 页：全屏地图页（真 vmap + 速度/转向浮层）──────────────── */

#ifdef SIM_WITH_UI
static bool vmap_mount(lv_obj_t *parent, int x, int y, int w, int h)
{
    lv_obj_t *holder = lv_obj_create(parent);

    lv_obj_remove_style_all(holder);
    lv_obj_set_size(holder, w, h);
    lv_obj_set_pos(holder, x, y);
    lv_obj_set_style_bg_color(holder, lv_color_hex(P_CARD), 0);
    lv_obj_set_style_bg_opa(holder, LV_OPA_COVER, 0);
    lv_obj_remove_flag(holder, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(holder, LV_OBJ_FLAG_OVERFLOW_VISIBLE);

    s_nav_view = vmap_view_create(holder, w, h, VMAP_CANVAS_MARGIN);
    if (s_nav_view == NULL) {
        L(parent, "vmap create failed", PX_MICRO, P_MUTE, 16, h / 2);
        return false;
    }
    vmap_boot_lonlat(&s_nav_lon, &s_nav_lat);
    vmap_view_bind_arrow_layer(s_nav_view, holder);
    vmap_view_set_font(s_nav_view, sim_font_cjk(15));
    vmap_view_set_center_icon(s_nav_view, navi_arrow_get(NAVI_ARROW_DARK));
    vmap_view_set_view(s_nav_view, s_nav_lon, s_nav_lat, 14);
    vmap_view_center_on(s_nav_view, s_nav_lon, s_nav_lat);
    vmap_view_set_scale(s_nav_view, 1.69);
    vmap_view_update_arrow(s_nav_view, s_nav_lon, s_nav_lat, 0.0f);
    if (!s_map_north) {
        vmap_view_set_heading_up(s_nav_view, true);
        vmap_view_set_heading(s_nav_view, 35.0f, (float)R.speed);
    }
    vmap_view_render(s_nav_view);
    s_nav_timer = lv_timer_create(nav_pump, 10, NULL);
    printf("helm: REAL vmap vp=%dx%d margin=%d\n", w, h,
           (int)vmap_view_get_margin(s_nav_view));
    fflush(stdout);
    return true;
}
#endif

static void ride_build_map(void)
{
#ifdef SIM_WITH_UI
    /* 地图从 y=24 开始，状态栏独占 0..24，不压内容。 */
    (void)vmap_mount(s_scr, 0, 24, 240, 296);
#else
    d_bg(s_scr, P_CARD);
    (void)B(s_scr, 0, 120, 240, 3, P_PAPER, LV_OPA_COVER, 0);
    (void)B(s_scr, 96, 24, 3, 296, P_PAPER, LV_OPA_COVER, 0);
    L(s_scr, "vmap (SIM_WITH_UI=OFF)", PX_MICRO, P_MUTE, 16, 148);
#endif
    /* 状态栏独占一行（地图页也是不透明底色）。 */
    statusbar_build();
    /* 页点：地图上垫一块纸色小底，保证三个点读得清。 */
    (void)B(s_scr, 8, 24, 38, 11, P_PAPER, (lv_opa_t)224, 5);
    ride_page_dots();

    /* 底部浮层：当前速度（大字）+ 右半块（导航转向 / 本次骑行时长）。 */
    {
        lv_obj_t *card = B(s_scr, 12, 236, 216, 76, P_PAPER, (lv_opa_t)242, 10);

        lv_obj_set_style_border_width(card, 1, 0);
        lv_obj_set_style_border_color(card, lv_color_hex(P_HAIR), 0);
        lv_obj_set_style_border_opa(card, LV_OPA_COVER, 0);
        (void)B(card, 0, 12, 3, 52, C_DEEP[M_RIDE], LV_OPA_COVER, 1);
        UR.map_speed = L(card, "", 36, P_INK, 14, 4);
        UR.map_unit = L(card, unit_speed(), PX_MICRO, P_MUTE, 14,
                        44);
        UR.map_dist = L(card, "", PX_MICRO, P_MUTE, 14, 58);
        UR.map_turn = L(card, "300 m", PX_VALUE, P_INK, 108, 4);
        UR.map_turn_sub = L(card, NAV_TURNS[s_nav_turn % 4], PX_MICRO, P_MUTE,
                            108, 32);
        (void)B(card, 99, 8, 1, 58, P_HAIR, LV_OPA_COVER, 0);
    }
    ride_refresh();
}

/* 骑行页入口：三页各自独立构建（不轮转的页内布局），KEY 左右切换。 */
static void ride_build(void)
{
    memset(&UR, 0, sizeof(UR));
    d_bg(s_scr, P_PAPER);
    if (s_ride_page == 1) {
        statusbar_build();
        ride_build_grid();
        ride_page_dots();
    } else if (s_ride_page == 2) {
        ride_build_map();       /* 内部：地图（y=24 起）+ 状态栏 + 页点 + 浮层 */
    } else {
        statusbar_build();
        ride_build_dial();
        ride_page_dots();
    }
}

/* ── 导航页（真 vmap）─────────────────────────────────────────── */

