static double week_total(void)
{
    double sum = 0.0;

    for (int i = 0; i < 7; i++) {
        sum += s_week[i];
    }
    return sum;
}

static int week_rides(void)
{
    int n = 0;

    for (int i = 0; i < 7; i++) {
        if (s_week[i] != 0) {
            n++;
        }
    }
    return n;
}

static int hr_zone(int bpm)
{
    if (bpm < 118) return 1;
    if (bpm < 132) return 2;
    if (bpm < 140) return 3;
    if (bpm < 160) return 4;
    return 5;
}

/** 心率指针落点 x（2px 宽：像素 x..x+1）。
 *
 *  分段线性，每格正好一个分区：五格等宽 30/30/31/30/31 px，格内再按该分区
 *  的 bpm 区间线性细分。这样「指针在第 i 格」⇔ `hr_zone(bpm) == i`，
 *  不会出现指针在 Z3 而四格显示 Z2 的矛盾。
 *
 *  t = (段号 + 段内比例) / 5 ∈ [0,1]，x = 64 + round(152·t) − 1。
 *  例：148 bpm → Z4(140..160) → t = (3 + 8/20)/5 = 0.68
 *      → x = 64 + round(103.36) − 1 = 166（像素 166..167，落在第 4 格 155..184）。
 *      120 bpm → Z2(118..132) → t = (1 + 2/14)/5 ≈ 0.2286
 *      → x = 64 + round(34.74) − 1 = 98（像素 98..99，落在第 2 格 94..123）。
 */
static int hr_bar_x(int bpm)
{
    double t;

    if (bpm < HR_MIN_BPM) bpm = HR_MIN_BPM;
    if (bpm > HR_MAX_BPM) bpm = HR_MAX_BPM;
    if (bpm < 118) {
        t = (double)(bpm - HR_MIN_BPM) / (118.0 - HR_MIN_BPM);
    } else if (bpm < 132) {
        t = 1.0 + (double)(bpm - 118) / (132.0 - 118.0);
    } else if (bpm < 140) {
        t = 2.0 + (double)(bpm - 132) / (140.0 - 132.0);
    } else if (bpm < 160) {
        t = 3.0 + (double)(bpm - 140) / (160.0 - 140.0);
    } else {
        t = 4.0 + (double)(bpm - 160) / (HR_MAX_BPM - 160.0);
    }
    t /= 5.0;
    {
        int x = HR_BAR_X0 + (int)lround((double)HR_BAR_W * t) - 1;

        if (x < HR_BAR_X0) x = HR_BAR_X0;
        if (x > HR_BAR_X0 + HR_BAR_W - BAR_PTR_W) {
            x = HR_BAR_X0 + HR_BAR_W - BAR_PTR_W;
        }
        return x;
    }
}

/** 最近 60 s 假心率序列的统计：均值四舍五入、峰值取最大值。
 *
 *  v[i] = clamp(R.hr + s_hr_delta[i], 60, 200)，i = 0..30；
 *  mean = (Σv + N/2) / N（整数除法 = 四舍五入）；
 *  peak = max(v)。
 *  例：R.hr = 148 时 Σv = 31·148 − 466 = 4122，
 *  mean = (4122 + 15)/31 = 4137/31 = 133，peak = 148 + 0 = 148。 */
static void hr_hist_stats(int *avg, int *peak)
{
    int sum = 0;
    int mx = -1000;

    for (int i = 0; i < HR_HIST_N; i++) {
        int v = R.hr + s_hr_delta[i];

        if (v < HR_MIN_BPM) v = HR_MIN_BPM;
        if (v > HR_MAX_BPM) v = HR_MAX_BPM;
        sum += v;
        if (v > mx) mx = v;
    }
    *avg = (sum + HR_HIST_N / 2) / HR_HIST_N;
    *peak = mx;
}

/* ── 单位 / 时间 / 坡度格式化（设置项真的影响显示）────────────────── */
#define KM_PER_MILE 1.609344

static double conv_dist(double km)
{
    return s_unit_mile ? km / KM_PER_MILE : km;
}

static double conv_speed(double kmh)
{
    return s_unit_mile ? kmh / KM_PER_MILE : kmh;
}

static const char *unit_dist(void) { return s_unit_mile ? "mile" : "km"; }
static const char *unit_speed(void) { return s_unit_mile ? "mph" : "km/h"; }

/** 当前时间（含时区与 12/24 小时制）；minutes 是本地 UTC+8 的分钟数。 */
static void fmt_clock(int minutes, char *buf, size_t n)
{
    int m = (minutes + (s_tz - 8) * 60) % (24 * 60);

    if (m < 0) m += 24 * 60;
    if (s_h24) {
        snprintf(buf, n, "%d:%02d", m / 60, m % 60);
    } else {
        int h = m / 60;
        const char *ap = (h >= 12) ? "PM" : "AM";

        h %= 12;
        if (h == 0) h = 12;
        snprintf(buf, n, "%d:%02d %s", h, m % 60, ap);
    }
}

/** 坡度：% ↔ °（同一个几何坡度两种表述）。 */
static double grade_val(double pct)
{
    return s_grade_deg ? atan(pct / 100.0) * 180.0 / 3.141592653589793 : pct;
}

static const char *grade_unit(void) { return s_grade_deg ? "°" : "%"; }

/** 自动暂停：速度 < 2 km/h 连续 10 s 触发；>= 2.5 km/h 自动恢复。 */
#define AUTO_PAUSE_ENTER_KMH 2.0
#define AUTO_PAUSE_EXIT_KMH  2.5
#define AUTO_PAUSE_HOLD_S    10

static void ride_step(void)
{
    R.seed = R.seed * 1103515245u + 12345u;
    R.t += 1.0;
    {
        const double n = (double)((R.seed >> 16) & 0x7FFF) / 32767.0 - 0.5;
        double sp = 22.5 + 5.5 * sin(R.t / 8.0) + 1.6 * n;

        /* 演示语义：每 60 s 有一个 14 s 的“红灯/推车”段（速度 0），
         * 自动暂停在静止 10 s 后触发、放行后自动恢复。 */
        if (fmod(R.t, 60.0) >= 46.0) {
            sp = 0.0;
        }
        if (sp > 0.0 && sp < 8.0) sp = 8.0;
        if (sp > 45.0) sp = 45.0;

static void helm_climb_axis(const int16_t * eles, uint32_t n,
    int32_t * mn, int32_t * mx)
{
    uint32_t i;
    int32_t lo = 32767;
    int32_t hi = -32767;
    int32_t pad;

    for (i = 0; i < n; i++) {
        if (eles[i] == (int16_t)VGRF_ELE_UNKNOWN) {
            continue;
        }
        if ((int32_t)eles[i] < lo) {
            lo = eles[i];
        }
        if ((int32_t)eles[i] > hi) {
            hi = eles[i];
        }
    }
    if (lo > hi) {
        lo = 0;
        hi = 100;
    }
    pad = (hi - lo) / 10;
    if (pad < 8) {
        pad = 8;
    }
    *mn = lo - pad;
    *mx = hi + pad;
}

/**
 * @brief 路线或近 30 分钟记录变化时重载海拔剖面。
 * @details 导航：按总里程均匀取样，并一次性写入 `s_climb_zone`（骑行中不重算坡度）。
 *          烘焙成功则隐藏图表、不再 `lv_chart_refresh`。
 *          未导航或烘焙失败：显示图表并 refresh 一次（「经过海拔」仍用青绿渐变）。
 */
static void helm_climb_profile_reload(void)
{
    int16_t eles[HELM_CLIMB_PROF_N];
    uint32_t n = 0;
    uint32_t now_idx = LV_CHART_POINT_NONE;
    uint32_t i;
    int32_t mn;
    int32_t mx;
    bool nav;
    int16_t last = 0;
    bool have = false;
    uint32_t fp_pts = 0;
    uint32_t fp_total_cm = 0;

    if (s_sh.climb_chart == NULL || s_sh.climb_ser == NULL) {
        return;
    }

    nav = helm_nav_on();
#if VMAP_ROUTE_ENABLE
    if (nav) {
        uint32_t cur = 0;

        n = map_page_nav_profile_ele(s_sh.map, eles, HELM_CLIMB_PROF_N, &cur);
        (void)map_page_nav_progress(s_sh.map, &fp_pts, &fp_total_cm, NULL, n);
        if (n >= 2u) {
            now_idx = cur;
        }
    } else
#endif
    if (helm_riding() && s_rec_ele_n >= 2u) {
        n = s_rec_ele_n;
        memcpy(eles, s_rec_ele, (size_t)n * sizeof(eles[0]));
        fp_pts = n;
        fp_total_cm = n;
    }

    if (s_sh.climb_title) {
        /* 非导航时这条剖面来自本机记录采样；还没采到点就明说「记录中」，
         * 而不是让人对着一张空图猜（用户 2026-09-26）。 */
        if (!nav && s_rec_ele_n < 2u) {
            helm_label_set(s_sh.climb_title, "记录中");
        } else {
            helm_label_set(s_sh.climb_title, nav ? "路线海拔" : "经过海拔");
        }
    }

    s_climb_fp_pts = fp_pts;
    s_climb_fp_total_cm = fp_total_cm;
    s_climb_fp_rec_n = nav ? 0 : (uint8_t)s_rec_ele_n;
    s_climb_fp_rec_slot = nav ? 0xffffffffu : s_rec_ele_slot;
    s_sh.climb_nav = nav;

    if (n < 2u) {
        s_sh.climb_n = 0;
        s_sh.climb_now = 0;
        helm_climb_canvas_hide();
        lv_obj_add_flag(s_sh.climb_chart, LV_OBJ_FLAG_HIDDEN);
        return;
    }

    for (i = 0; i < n; i++) {
        if (eles[i] != (int16_t)VGRF_ELE_UNKNOWN) {
            last = eles[i];
            have = true;
            break;
        }
    }
    if (!have) {
        s_sh.climb_n = 0;
        helm_climb_canvas_hide();
        lv_obj_add_flag(s_sh.climb_chart, LV_OBJ_FLAG_HIDDEN);
        return;
    }

    for (i = 0; i < n; i++) {
        int16_t e = eles[i];

        if (e == (int16_t)VGRF_ELE_UNKNOWN) {
            e = last;
        } else {
            last = e;
        }
        s_climb_eles[i] = e;
    }
    if (nav && n >= 2u) {
        uint32_t step_cm = (fp_total_cm > 0u) ? (fp_total_cm / (n - 1u)) : 0u;

        if (step_cm < 1u) {
            step_cm = 1u;
        }
        for (i = 0; i + 1u < n; i++) {
            s_climb_zone[i] = helm_climb_grade_zone(s_climb_eles[i],
                s_climb_eles[i + 1u], step_cm);
        }
    }

    helm_climb_axis(s_climb_eles, n, &mn, &mx);
    if (lv_chart_get_point_count(s_sh.climb_chart) != n) {
        lv_chart_set_point_count(s_sh.climb_chart, n);
    }
    lv_chart_set_axis_range(s_sh.climb_chart, LV_CHART_AXIS_PRIMARY_Y, mn, mx);
    {
        lv_color_t col = helm_color_snap(HELM_COLOR_CLIMB);

        if (!lv_color_eq(lv_chart_get_series_color(s_sh.climb_chart,
                s_sh.climb_ser), col)) {
            lv_chart_set_series_color(s_sh.climb_chart, s_sh.climb_ser, col);
        }
    }
    {
        int32_t * y = lv_chart_get_series_y_array(s_sh.climb_chart,
            s_sh.climb_ser);

        if (y != NULL) {
            for (i = 0; i < n; i++) {
                y[i] = (int32_t)s_climb_eles[i];
            }
        }
    }
    lv_chart_set_x_start_point(s_sh.climb_chart, s_sh.climb_ser, 0);
    s_sh.climb_n = (uint8_t)n;
    s_sh.climb_now = (uint8_t)((nav && now_idx < n) ? now_idx : (n - 1u));
    if (nav && helm_climb_canvas_bake()) {
        return;
    }
    helm_climb_canvas_hide();
    lv_obj_remove_flag(s_sh.climb_chart, LV_OBJ_FLAG_HIDDEN);
    lv_chart_refresh(s_sh.climb_chart);
}

