    /** @brief 最新 GNSS 定位。 */
    float longitude;
    float latitude;
    float altitude_m;
    bool has_altitude;
    float gnss_altitude_m;
    bool gnss_has_altitude;
    float gain_m;
    float loss_m;
    /** @name 会话内海拔极值（只在记录中统计，与 gain/loss 同一口径）。
     *  @note `alt_range_valid` 为假时**不要**把 0 当有效值用（0 m 是合法海拔）。
     *  @{
     */
    float altitude_max_m;
    float altitude_min_m;
    bool alt_range_valid;
    /** @} */
    float grade_pct;
