/** 生成 2 km 假剖面：9 段不同坡度，保证灰/模式浅色/红三档都出现。 */
static void elev_profile_gen(void)
{
    /* n = 段数，pct = 该段坡度百分数；合计 59 段。 */
    static const struct {
        uint8_t n;
        double pct;
    } plan[] = {
        { 6, 0.5 },  /* 平路起步 */
        { 6, 2.6 },  /* 缓上（仍算平路） */
        { 6, 5.5 },  /* 中坡 */
        { 6, 9.0 },  /* 陡坡 */
        { 7, -3.5 }, /* 下坡 */
        { 7, 4.5 },  /* 中坡 */
        { 6, 7.5 },  /* 中陡 */
        { 6, 0.8 },  /* 高处平路台地 */
        { 6, 10.0 }, /* 最后一段陡坡 */
        { 3, -4.5 }, /* 下坡收尾 */
    };
    const double step = ELEV_VIEW_M / (double)(ELEV_PROF_N - 1);
    double e = 326.0; /* 与骑行页当前海拔（R.elevation）对齐 */
    int k = 0;

    s_elev[0] = e;
    for (size_t p = 0; p < sizeof(plan) / sizeof(plan[0]); p++) {
        for (int i = 0; i < plan[p].n && k + 1 < ELEV_PROF_N; i++) {
            e += step * plan[p].pct / 100.0;
            s_elev[k + 1] = e;
            k++;
        }
    }
    for (int i = 0; i + 1 < ELEV_PROF_N; i++) {
        const double g = fabs(s_elev[i + 1] - s_elev[i]) / step * 100.0;

        s_elev_zone[i] = (g < ELEV_GRADE_FLAT) ? 0u
                       : (g < ELEV_GRADE_STEEP) ? 1u
                                                : 2u;
    }
}

