static uint32_t rt_disp_win_target(rt_conf_t conf)
{
    if (conf == RT_CONF_HIGH) {
        return RT_DISP_WIN_HIGH_MS;
    }

    if (conf == RT_CONF_MID) {
        return RT_DISP_WIN_MID_MS;
    }

    return RT_DISP_WIN_LOW_MS;
}

static float rt_disp_blend_target(rt_conf_t conf)
{
    if (conf == RT_CONF_HIGH) {
        return 0.85f;
