    tri.p[1].x = p2.x;
    tri.p[1].y = y_base;
    tri.p[2].x = p1.x;
    tri.p[2].y = y_base;
    lv_draw_triangle(layer, &tri);

    lv_draw_line_dsc_init(&ld);
    ld.color = stroke;
    ld.width = lw > 0 ? lw : 2;
    ld.opa = LV_OPA_COVER;
    ld.round_start = 1;
    ld.round_end = 1;
    ld.p1 = p1;
    ld.p2 = p2;
    lv_draw_line(layer, &ld);
}

