bool helm_shell_demo_page(const char * name)
{
    helm_page_id_t id;
    uint8_t * idx;

    if (name == NULL) {
        return false;
    }

    if (strcmp(name, "ring") == 0) {
        id = HELM_PAGE_RING;
    } else if (strcmp(name, "standby") == 0) {
        id = HELM_PAGE_STANDBY;
    } else if (strcmp(name, "ride") == 0) {
        id = HELM_PAGE_DATA;
    } else if (strcmp(name, "data") == 0) {
        id = HELM_PAGE_DATA_ALL;
    } else if (strcmp(name, "map") == 0) {
        id = HELM_PAGE_MAP;
    } else if (strcmp(name, "turn") == 0) {
        id = HELM_PAGE_TURN;
    } else if (strcmp(name, "climb") == 0) {
        id = HELM_PAGE_CLIMB;
    } else {
        return false;
    }

    s_demo_page = id;
    idx = helm_active_idx();
    if (helm_in_session()) {
        /* 骑行轮转：骑行页 / 数据页 / 地图页 / 海拔页。 */
        switch (id) {
        case HELM_PAGE_DATA_ALL:
            *idx = 1;
            break;
        case HELM_PAGE_MAP:
            *idx = 2;
            break;
        case HELM_PAGE_CLIMB:
            *idx = 3;
            break;
        default:
            *idx = 0;
