 * @param unit 单位标签（可为 NULL）。
 */
static void helm_paint_speed_pair(lv_obj_t * num, lv_obj_t * unit)
{
    uint32_t ink = helm_live_speed_ink();

    helm_set_text_hex(num, ink);
    helm_set_text_hex(unit, ink);
}

