/** @brief 页面根坐标版的 trig（与环形页 helm_ring_trig 同一算法，不引 libm）。 */
static int helm_dial_trig(int32_t v, int r)
{
    int64_t p = (int64_t)v * r;

    if (p >= 0) {
        return (int)((p + 16384) / 32767);
    }
    return (int)((p - 16384) / 32767);
}

