static void helm_show(lv_obj_t * obj, bool on)
{
    if (obj == NULL) {
        return;
    }

    if (on) {
        if (lv_obj_has_flag(obj, LV_OBJ_FLAG_HIDDEN)) {
            lv_obj_clear_flag(obj, LV_OBJ_FLAG_HIDDEN);
            lv_obj_move_foreground(obj);
        }
    } else if (!lv_obj_has_flag(obj, LV_OBJ_FLAG_HIDDEN)) {
        lv_obj_add_flag(obj, LV_OBJ_FLAG_HIDDEN);
    }
}
static void helm_build_ride_dots(lv_obj_t * root)
{
    lv_obj_t * strip;
    int i;

    strip = lv_obj_create(root);
    lv_obj_remove_style_all(strip);    lv_obj_set_pos(strip, 8, 0);
    lv_obj_set_size(strip, 40, 11);
