    lv_obj_set_style_bg_opa(strip, LV_OPA_90, 0);
    lv_obj_set_style_radius(strip, 5, 0);
    lv_obj_add_flag(strip, LV_OBJ_FLAG_FLOATING);
    lv_obj_add_flag(strip, LV_OBJ_FLAG_HIDDEN);
    lv_obj_clear_flag(strip, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(strip, LV_OBJ_FLAG_SCROLLABLE);
    s_sh.ride_dots = strip;

    for (i = 0; i < 3; i++) {
        s_sh.ride_dot[i] = helm_dial_box(strip, 4 + i * 10, 2, 7, 7,
                                         HELM_COLOR_TRACK, LV_OPA_COVER, 3);
    }
}

